insert into public.email_automations(id,key,name,trigger_type,is_active) values('9c349723-4bed-5d0d-9ad5-60bafc976fca','course_month-strength','Месяц силы','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('month-strength','Месяц силы','practicum','https://zamkovoi.yoga/m3/',90,3,5,'9c349723-4bed-5d0d-9ad5-60bafc976fca','57513837c49c495f589e90b639a312c5d56069cc3e666e6c86bea42e94f31ecd') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('f3b42871-fc01-5aa4-a8b4-44b0e6e0cc65','9c349723-4bed-5d0d-9ad5-60bafc976fca','Урок 1',1,0,'{Месяц силы} Добро пожаловать!','{"ru":"{Месяц силы} Добро пожаловать!"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png" alt="Месяц силы" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца целенаправленно поработать с состояниями силы, решительности, целеустремлённости, пассионарности. Уроки этого практикума я проводил в формате прямых эфиров из четырёх знаковых мест: Самарканда, Бухары, Хивы и Москвы. Самарканд, Бухара и Хива - одни из древнейших городов мира, расположенные на Великом Шелковом пути, центры науки, культуры и торговли древнего мира. Ну а Москва в настоящее время - крупнейший город России, и в каком-то смысле - центр силы. Занимаясь, вы сможете ощутить интереснейшую энергетику этих мест. Прочитайте это письмо полностью, чтобы понимать, что вас ожидает.</p><p></p><p>1. Расписание совместных практик</p><p></p><p>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке «День». Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p>2. Техника безопасности</p><p></p><p>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p>3. Ответы на вопросы</p><p></p><p>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p>4. Ваши регулярные действия - условие результатов</p><p></p><p>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите укрепить здоровье. Так что выполняйте асаны, пранаяму, медитацию, питайтесь тем, что вас исцеляет, корректируйте режим дня, занимайтесь спортом, общайтесь с природой. Каждое своё действие совершайте с целью и с ощущением восстановления целостности и оздоравливания на уровне тела.</p><p></p><p>5. Первый урок</p><p></p><p>А теперь вы готовы перейти к первому уроку. В нём мы рассмотрим тему выработки здоровых привычек, и освоим технику суставной гимнастики, которую я рекомендую вам выполнять ежедневно в течение этого месяца. Урок довольно длинный, так как очень важно правильно сформулировать намерение и продумать небольшую практику на каждый день. Так как этот практикум я проводил в прямом эфире, вы услышите мои комментарии и ответы на задаваемые вопросы. Они помогут вам избежать распространённых ошибок.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе, на вкладке „День“.</p><p></p><p>Желаю вам плодотворного месяца!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png\" alt=\"Месяц силы\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца целенаправленно поработать с состояниями силы, решительности, целеустремлённости, пассионарности. Уроки этого практикума я проводил в формате прямых эфиров из четырёх знаковых мест: Самарканда, Бухары, Хивы и Москвы. Самарканд, Бухара и Хива - одни из древнейших городов мира, расположенные на Великом Шелковом пути, центры науки, культуры и торгов